export const suits = {
  major: { name: 'Major Arcana', swedish: 'Stora arkanan', element: '', mark: 'star' },
  wands: { name: 'Wands', swedish: 'Stavar', element: 'Eld', mark: 'flame' },
  cups: { name: 'Cups', swedish: 'Bägare', element: 'Vatten', mark: 'cup' },
  swords: { name: 'Swords', swedish: 'Svärd', element: 'Luft', mark: 'sword' },
  pentacles: { name: 'Pentacles', swedish: 'Mynt', element: 'Jord', mark: 'coin' },
};

const majorNumbers = ['0', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI', 'XII', 'XIII', 'XIV', 'XV', 'XVI', 'XVII', 'XVIII', 'XIX', 'XX', 'XXI'];
const rankSwedish = ['Ess', 'Två', 'Tre', 'Fyra', 'Fem', 'Sex', 'Sju', 'Åtta', 'Nio', 'Tio', 'Page', 'Riddare', 'Drottning', 'Kung'];
const rankEnglish = ['Ace', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Page', 'Knight', 'Queen', 'King'];
const rankNumber = ['A', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'P', 'R', 'D', 'K'];
const rows = (text) => text.trim().split('\n').map((row) => row.split('|'));

function card(suit, index, name, english, number, [keywords, imagery, upright, reversed]) {
  return { id: `${suit}-${index}`, suit, index, name, english, number, keywords: keywords.split(', '), imagery, upright, reversed };
}

export const deck = [
  ...rows(majorText).map(([name, english, ...meanings], index) => card('major', index, name, english, majorNumbers[index], meanings)),
  ...Object.entries({ wands: wandText, cups: cupText, swords: swordText, pentacles: pentacleText }).flatMap(([suit, text]) =>
    rows(text).map((meanings, index) => {
      const swedish = suits[suit].swedish.toLowerCase();
      const name = index === 0 || index >= 10 ? `${rankSwedish[index]} i ${swedish}` : `${rankSwedish[index]} ${swedish}`;
      return card(suit, index + 1, name, `${rankEnglish[index]} of ${suits[suit].name}`, rankNumber[index], meanings);
    }),
  ),
];

export const cardsById = new Map(deck.map((item) => [item.id, item]));
